[{"tweet_id": "166636", "author_id": "SpotifyCares", "inbound": "False", "created_at": "Fri Nov 24 20:35:26 +0000 2017", "text": "@154709 Hey there! Thanks for the feedback. Your Time Capsule is made of personalised content uniquely created based on your previous listening patterns. Just to check, are you experiencing issues with the Shuffle feature on all of your playlists? /PC", "response_tweet_id": "166637", "in_response_to_tweet_id": "166638"}, {"tweet_id": "166637", "author_id": "154709", "inbound": "True", "created_at": "Fri Nov 24 20:39:42 +0000 2017", "text": "@SpotifyCares Thanks for getting back to me. My question is - when you "shuffle" a playlist is it truly random?  For at least the past year it feels like the same songs keep coming up even though there are over 2k on the playlist.", "response_tweet_id": "166639", "in_response_to_tweet_id": "166636"}, {"tweet_id": "166639", "author_id": "SpotifyCares", "inbound": "False", "created_at": "Fri Nov 24 22:12:48 +0000 2017", "text": "@154709 No worries. We’ve recently made some improvements to our shuffle algorithm. We’d love to hear your feedback here: https://t.co/T3vZnSL3od. If there's anything else, just give us a shout /PC", "response_tweet_id": "166640,166641", "in_response_to_tweet_id": "166637"}, {"tweet_id": "166640", "author_id": "SpotifyCares", "inbound": "False", "created_at": "Fri Nov 24 22:37:50 +0000 2017", "text": "@154709 We hear you! Rest assured we're always looking for ways to improve Spotify, and we'll be forwarding your feedback on to the right folks 🙂 /TB", "response_tweet_id": "166642", "in_response_to_tweet_id": "166639"}, {"tweet_id": "166642", "author_id": "154709", "inbound": "True", "created_at": "Fri Nov 24 22:42:00 +0000 2017", "text": "@SpotifyCares Preciate ya 🙏", "response_tweet_id": "166643", "in_response_to_tweet_id": "166640"}, {"tweet_id": "166643", "author_id": "SpotifyCares", "inbound": "False", "created_at": "Fri Nov 24 22:49:38 +0000 2017", "text": "@154709 Anytime! Let us know if you ever need us again. We'd be... https://t.co/LgAM6ky9Vv /AN", "response_tweet_id": "", "in_response_to_tweet_id": "166642"}, {"tweet_id": "166641", "author_id": "154709", "inbound": "True", "created_at": "Fri Nov 24 22:16:00 +0000 2017", "text": "@SpotifyCares My feedback is this is incredibly annoying", "response_tweet_id": "", "in_response_to_tweet_id": "166639"}, {"tweet_id": "166638", "author_id": "154709", "inbound": "True", "created_at": "Fri Nov 24 17:46:55 +0000 2017", "text": "@115888 the "Time Capsule" playlist you made for me is great but it's ALL songs on my main playlist that just never come up on shuffle.  

Why do the same 20-25 songs ALWAYS play? 

@SpotifyCares", "response_tweet_id": "166636", "in_response_to_tweet_id": ""}]

